use Illuminate\Http\Client\RequestException;

public function rates(string $base): array
{
    try {
        return Http::timeout(3)
            ->retry(3, 1)
            ->throw()
            ->get('https://api.example.com/v1/rates', ['base' => $base])
            ->json('rates', []);
    } catch (ConnectionException|RequestException $e) {
        report($e);

        return [];
    }
}
